import {test} from 'node:test';
import assert from 'node:assert/strict';
import {createHandler} from '../supabase/functions/onoff-api/server.js';

const ADMIN='10000000-0000-4000-8000-000000000001',MEMBER='10000000-0000-4000-8000-000000000002';
const fixture=({role='member',status='approved',anonymous=false,valid=true,coach_permissions=[],approved_at=null,rejected_at=null,delete_requested_at=null}={})=>{
 const writes=[],tables={gym_members:[{id:MEMBER,name:'테스트 회원',gender:'male',privacy_version:'privacy-2026-11-05',role,status,coach_permissions,approved_at,rejected_at,delete_requested_at},{id:ADMIN,name:'운영자',role:'admin',status:'approved'}],gym_settings:[{key:'releaseTime',value:'22:00'},{key:'revision',value:0},{key:'tvPassword',value:{salt:'private',hash:'private'}}],gym_member_notes:[{user_id:MEMBER,note:'운영자 비공개 메모'}],gym_records:[],gym_holiday_cache:[{key:'KR',updated_at:'2026-11-02T00:00:00Z',body:{dates:{},source:'fixture'}}],gym_workouts:[{key:'2026-11-02_WOD',date:'2026-11-02',program:'WOD',release_at:'2026-11-01T13:00:00Z',body:{date:'2026-11-02',program:'WOD',sections:[{title:'Front Squat',text:'5 reps',record:true,kind:'중량',movements:['Front Squat']}]}},{key:'2026-11-03_WOD',date:'2026-11-03',program:'WOD',release_at:'2026-11-02T13:00:00Z',body:{date:'2026-11-03',program:'WOD',sections:[{title:'비공개 미래 운동',text:'secret'}]}}]};
 const db={from(name){let data=structuredClone(tables[name]||[]),single=false;const q={select(){return q},contains(){return q},eq(k,v){data=data.filter(x=>x[k]===v);return q},gt(k,v){data=data.filter(x=>x[k]>v);return q},lte(k,v){data=data.filter(x=>x[k]<=v);return q},or(){return q},order(){return q},limit(n){data=data.slice(0,n);return q},maybeSingle(){single=true;return q},then(resolve,reject){return Promise.resolve({data:single?data[0]||null:data,error:null}).then(resolve,reject)}};return q;},rpc(name,p){writes.push(p);return Promise.resolve({data:{ok:true},error:null})}};
 const handle=createHandler(db,{verifyUser:async()=>valid?{id:MEMBER,is_anonymous:anonymous,user_metadata:{role:'admin'}}:null,now:()=>new Date('2026-11-02T01:00:00Z')});
 async function request(path,{body,token='valid',method=body?'POST':'GET',origin='https://nuclearstark.github.io'}={}){const headers={Origin:origin};if(token)headers.Authorization='Bearer '+token;if(body)headers['Content-Type']='application/json';const res=await handle(new Request('https://project.supabase.co/functions/v1/onoff-api'+path,{method,headers,body:body?JSON.stringify(body):undefined}));return {status:res.status,value:await res.json(),headers:res.headers};}
 return {tables,writes,request,db};
};

test('Supabase API exposes no member data without a verified non-anonymous Auth session',async()=>{
 for(const options of [{},{valid:false},{anonymous:true}]){
  const f=fixture(options);const r=await f.request('/api/bootstrap',{token:options.valid===undefined&&!options.anonymous?null:'bad'});assert.equal(r.status,401);assert.equal(r.value.viewer,undefined);assert.equal(f.writes.length,0);
 }
});
test('account deletion never accepts an unauthenticated caller-selected identity',async()=>{const f=fixture();const r=await f.request('/api/account/delete',{body:{id:ADMIN,password:'guess',confirmed:true},token:null});assert.equal(r.status,401);assert.equal(f.writes.length,0);});

test('API rejects disallowed origins, unexpected methods and JSON role escalation',async()=>{
 const f=fixture();assert.equal((await f.request('/api/bootstrap',{origin:'https://evil.example'})).status,403);
 assert.equal((await f.request('/api/attendance')).status,405);
 assert.equal((await f.request('/api/members',{body:{id:ADMIN,role:'admin',status:'approved'}})).status,403);assert.equal(f.writes.length,0);
});
test('Cloudflare production origin can connect while authentication and exact origin restrictions remain enforced',async()=>{
 const f=fixture(),origin='https://onoffgym.pages.dev';
 const member=await f.request('/api/bootstrap',{origin});
 assert.equal(member.status,200);assert.equal(member.headers.get('Access-Control-Allow-Origin'),origin);
 const writesAfterMember=f.writes.length;
 const unauthenticated=await f.request('/api/bootstrap',{origin,token:null});
 assert.equal(unauthenticated.status,401);assert.equal(unauthenticated.headers.get('Access-Control-Allow-Origin'),origin);assert.equal(unauthenticated.value.viewer,undefined);
 const handle=createHandler(f.db,{verifyUser:async()=>null});
 const preflight=await handle(new Request('https://project.supabase.co/functions/v1/onoff-api/api/bootstrap',{method:'OPTIONS',headers:{Origin:origin,'Access-Control-Request-Method':'GET','Access-Control-Request-Headers':'authorization,apikey'}}));
 assert.equal(preflight.status,204);assert.equal(preflight.headers.get('Access-Control-Allow-Origin'),origin);
 for(const other of ['https://another-app.pages.dev','https://onoffgym.pages.dev.evil.example','https://preview.onoffgym.pages.dev','http://onoffgym.pages.dev'])assert.equal((await f.request('/api/bootstrap',{origin:other})).status,403);
 assert.equal(f.writes.length,writesAfterMember);
 assert.equal((await f.request('/api/bootstrap',{origin:'https://nuclearstark.github.io'})).status,200);
});
