test('operators can reject a never-approved signup with an optional bounded reason',async()=>{
 const f=fixture({role:'admin'});f.tables.gym_members[1].status='pending';
 const rejected=await f.request('/api/members',{body:{id:ADMIN,role:'member',status:'rejected',reason:'실명을 확인해주세요.'}});
 assert.equal(rejected.status,200);assert.equal(f.writes[0].actor,MEMBER);assert.equal(f.writes[0].p.reason,'실명을 확인해주세요.');assert.equal(f.writes[0].p.status,'suspended');
 const fallback=fixture({role:'admin'});fallback.tables.gym_members[1].status='pending';
 assert.equal((await fallback.request('/api/members',{body:{id:ADMIN,role:'member',status:'suspended',reason:'  '}})).status,200);
 assert.match(fallback.writes[0].p.reason,/카운터/);
 for(const reason of ['x'.repeat(501),{private:'object'}])assert.equal((await f.request('/api/members',{body:{id:ADMIN,role:'member',status:'rejected',reason}})).status,400);
 const approved=fixture({role:'admin'});approved.tables.gym_members[1].approved_at='2026-10-01T00:00:00Z';
 assert.equal((await approved.request('/api/members',{body:{id:ADMIN,role:'member',status:'rejected'}})).status,409);assert.equal(approved.writes.length,0);
 assert.equal((await fixture({role:'coach'}).request('/api/members',{body:{id:ADMIN,role:'member',status:'rejected'}})).status,403);
});
