test('coach permissions start empty, never grant member administration, and reveal only a minimal record roster',async()=>{for(const key of [[],['records.create'],['banner'],['tv']]){const f=fixture({role:'coach',coach_permissions:key});for(const path of ['/api/members','/api/member-note','/api/member-name','/api/membership','/api/membership/delete','/api/storage-usage'])assert.equal((await f.request(path,{body:path==='/api/storage-usage'?undefined:{id:ADMIN}})).status,403,path);const b=(await f.request('/api/bootstrap')).value;assert.deepEqual(b.members,[]);assert.deepEqual(b.memberships,[]);assert.deepEqual(b.membershipEvents,[]);assert.deepEqual(b.memberAttendance,[]);assert.ok(!JSON.stringify(b).includes('운영자 비공개 메모'));if(key.includes('records.create')){assert.ok(b.recordMembers.length);assert.deepEqual(Object.keys(b.recordMembers[0]).sort(),['id','name','status']);}else assert.deepEqual(b.recordMembers,[]);}});
