test('ACC permissions are independent, opt-in, rechecked for create/update/delete and never derived from metadata',async()=>{const body={date:'2026-11-02',text:'Optional workout',movements:['Free text']};for(const options of [{},{role:'coach'},{role:'coach',coach_permissions:['workouts.create','videos']},{role:'coach',status:'pending',coach_permissions:['acc.create']}]){const f=fixture(options);assert.equal((await f.request('/api/acc',{body})).status,403);assert.equal(f.writes.length,0);}const f=fixture({role:'coach',coach_permissions:['acc.create']});assert.equal((await f.request('/api/acc',{body})).status,200);assert.deepEqual(f.writes[0],{actor:MEMBER,target_date:body.date,p:{text:body.text,movements:body.movements,overviewId:''}});f.tables.gym_acc_workouts=[{date:body.date,body}];assert.equal((await f.request('/api/acc',{body})).status,403);assert.equal((await f.request('/api/acc',{body:{...body,action:'delete'}})).status,403);for(const key of ['acc.update','acc.delete']){f.tables.gym_members[0].coach_permissions=[key];assert.equal((await f.request('/api/acc',{body:key.endsWith('delete')?{date:body.date,action:'delete'}:body})).status,200);}assert.equal((await fixture({role:'admin'}).request('/api/acc',{body:{...body,overview:'https://evil.example/video'}})).status,400);});
test('ACC bootstrap obeys release times; its unpublished read grant does not expose class content or TV credentials',async()=>{for(const granted of [false,true]){const f=fixture({role:'coach',coach_permissions:granted?['acc.read']:[]});f.tables.gym_acc_workouts=[{date:'2026-11-10',release_at:'2026-11-09T13:00:00Z',body:{text:'unpublished ACC'}},{date:'2026-11-01',release_at:'2026-10-31T13:00:00Z',body:{text:'released ACC'}}];const b=(await f.request('/api/bootstrap')).value;assert.equal(!!b.accWorkouts['2026-11-10'],granted);assert.ok(b.accWorkouts['2026-11-01']);assert.equal(b.workouts['2026-11-03_WOD'],undefined);assert.equal(b.tv,undefined);const preview=(await f.request('/api/bootstrap?view=member')).value;assert.equal(preview.accWorkouts['2026-11-10'],undefined);}});
test('video catalogue resolves deleted categories, omits tombstoned default movements and keeps 1RM records',async()=>{const f=fixture();f.tables.gym_movements=[{name:'Front Squat',body:{name:'Front Squat'},deleted:true},{name:'Isolated Movement',body:{name:'Isolated Movement',notes:'custom'},category_id:'custom',deleted:false}];f.tables.gym_video_categories=[{id:'custom',label:'새 분류',position:0}];const b=(await f.request('/api/bootstrap')).value;assert.equal(b.library.some(x=>x.name==='Front Squat'),false);assert.ok(b.library.every(x=>x.categoryId==='custom'));assert.deepEqual(b.videoCategories,[['custom','새 분류']]);assert.ok(b.rmCatalogue.some(x=>x.name==='Front Squat'));});
test('category mutations and movement deletion require videos permission and bind actor from verified identity',async()=>{for(const options of [{},{role:'coach'},{role:'coach',coach_permissions:['rm']},{role:'coach',status:'suspended',coach_permissions:['videos']}]){const f=fixture(options);for(const [path,body]of [['/api/video-categories',{action:'add',label:'New'}],['/api/movements/delete',{name:'Front Squat'}]])assert.equal((await f.request(path,{body})).status,403);assert.equal(f.writes.length,0);}const f=fixture({role:'coach',coach_permissions:['videos']});assert.equal((await f.request('/api/video-categories',{body:{action:'add',label:'Custom',actor:ADMIN}})).status,200);assert.equal(f.writes[0].actor,MEMBER);assert.equal(f.writes[0].p.action,'category-add');assert.equal((await f.request('/api/movements/delete',{body:{name:'Front Squat',actor:ADMIN}})).status,200);assert.deepEqual(f.writes[1],{actor:MEMBER,p:{action:'movement-delete',name:'Front Squat'}});});

test('points and coupons expose only the verified account and no PIN hash, attempts or other balances',async()=>{const f=fixture();f.tables.gym_point_config=[{singleton:true,enabled:false,attendance_points:10,record_points:20,pin_hash:'private-pin-hash'}];f.tables.gym_point_accounts=[{user_id:MEMBER,balance:31},{user_id:ADMIN,balance:999}];f.tables.gym_point_coupons=[{id:'own',user_id:MEMBER,name:'Own',remaining:1},{id:'other',user_id:ADMIN,name:'Other',remaining:2}];f.tables.gym_point_ledger=[{user_id:MEMBER,amount:10},{user_id:ADMIN,amount:999}];const b=(await f.request('/api/points')).value;assert.equal(b.balance,31);assert.deepEqual(b.coupons.map(c=>c.id),['own']);assert.equal(b.ledger.length,1);assert.ok(!JSON.stringify(b).includes('private-pin-hash'));assert.equal(b.pinConfigured,undefined);const boot=(await f.request('/api/bootstrap')).value;assert.equal(boot.points.balance,31);assert.equal((await f.request('/api/points/admin')).status,403);assert.equal((await fixture({status:'pending'}).request('/api/points')).status,403);});
test('point settings/products are admin-only; record/RM coach permission never grants point management',async()=>{for(const opt of [{},{role:'coach',coach_permissions:['records.create','rm','videos']},{role:'admin',status:'suspended'}]){const f=fixture(opt);for(const path of ['/api/points/settings','/api/points/product','/api/points/product/delete'])assert.equal((await f.request(path,{body:{}})).status,403);assert.equal(f.writes.length,0);}const f=fixture({role:'admin'});assert.equal((await f.request('/api/points/settings',{body:{enabled:false,attendancePoints:10,recordPoints:20,actor:ADMIN,pin:''}})).status,200);assert.deepEqual(f.writes[0],{actor:MEMBER,p:{action:'settings',enabled:false,attendancePoints:10,recordPoints:20,pin:''}});for(const change of [{attendancePoints:-1},{recordPoints:1.5},{pin:'12345'},{enabled:'true'}])assert.equal((await f.request('/api/points/settings',{body:{enabled:true,attendancePoints:10,recordPoints:20,...change}})).status,400);});
test('exchange/use only forward IDs and a stable retry ID; amounts and caller-selected identity are ignored',async()=>{const f=fixture(),productId=crypto.randomUUID(),couponId=crypto.randomUUID(),requestId=crypto.randomUUID();assert.equal((await f.request('/api/points/exchange',{body:{productId,requestId,expectedPrice:30,expectedUses:3,price:0,balance:999999,actor:ADMIN}})).status,200);assert.deepEqual(f.writes[0],{actor:MEMBER,p:{action:'exchange',productId,requestId,expectedPrice:30,expectedUses:3}});assert.equal((await f.request('/api/points/use',{body:{couponId,requestId,pin:'0000',remaining:999,actor:ADMIN}})).status,200);assert.deepEqual(f.writes[1],{actor:MEMBER,p:{action:'use',couponId,requestId,pin:'0000'}});assert.equal((await f.request('/api/points/exchange',{body:{productId,requestId:'bad'}})).status,400);f.db.rpc=async()=>({data:{ok:false,status:429,error:'비밀번호 입력 횟수를 초과했어요.'},error:null});assert.equal((await f.request('/api/points/use',{body:{couponId,requestId,pin:'0000'}})).status,429);});
test('point rules and manual grants require approved admin, bind actor and ignore caller-selected credited amounts',async()=>{const memberId=ADMIN,requestId=crypto.randomUUID();for(const options of [{},{role:'coach',coach_permissions:['push','rm']},{role:'admin',status:'pending'}]){const f=fixture(options);for(const path of ['/api/points/rule','/api/points/rule/delete','/api/points/grant'])assert.equal((await f.request(path,{body:{}})).status,403);assert.equal(f.writes.length,0);}const f=fixture({role:'admin'});assert.equal((await f.request('/api/points/grant',{body:{memberId,requestId,amount:25,reason:'행사 참여',actor:ADMIN,granted:999}})).status,200);assert.deepEqual(f.writes[0],{actor:MEMBER,p:{action:'grant',memberId,requestId,amount:25,reason:'행사 참여',ruleId:null}});assert.equal((await f.request('/api/points/grant',{body:{memberId,requestId,ruleId:'isolated',reason:'이벤트',amount:999}})).status,200);assert.equal(f.writes[1].p.amount,undefined);assert.equal((await f.request('/api/points/rule',{body:{kind:'manual',name:'이벤트',amount:10}})).status,200);assert.equal(f.writes[2].p.action,'rule-save');for(const body of [{memberId,requestId,amount:-1,reason:'x'},{memberId,requestId,amount:1,reason:''},{memberId:'bad',requestId,amount:1,reason:'x'}])assert.equal((await f.request('/api/points/grant',{body})).status,400);});
test('balance cap settings preserve unspecified legacy rates and reject negative or fractional caps',async()=>{const f=fixture({role:'admin'});assert.equal((await f.request('/api/points/settings',{body:{enabled:true,maxBalance:100,pin:''}})).status,200);assert.deepEqual(f.writes[0].p,{action:'settings',enabled:true,maxBalance:100,pin:''});assert.equal((await f.request('/api/points/settings',{body:{enabled:true,maxBalance:null}})).status,200);for(const maxBalance of [0,-1,1.5,9000000000001])assert.equal((await f.request('/api/points/settings',{body:{enabled:true,maxBalance}})).status,400);});
test('coupon expiry is exposed for the owner and member point balances are operator-only',async()=>{const f=fixture({role:'admin'});f.tables.gym_point_accounts=[{user_id:MEMBER,balance:20},{user_id:ADMIN,balance:70}];f.tables.gym_point_coupons=[{id:'own',user_id:MEMBER,remaining:1,expires_at:'2026-11-01T00:00:00Z'}];let b=(await f.request('/api/bootstrap')).value;assert.equal(b.points.coupons[0].expired,true);assert.equal(b.members.find(m=>m.id===ADMIN).pointBalance,70);f.tables.gym_members[0].role='coach';f.tables.gym_members[0].coach_permissions=['records.create'];b=(await f.request('/api/bootstrap')).value;assert.deepEqual(b.members,[]);assert.equal(b.points.balance,20);assert.equal(JSON.stringify(b).includes('pointBalance'),false);});
test('archiving an RM item requires delegated RM permission and never targets a member record ID',async()=>{const f=fixture();assert.equal((await f.request('/api/rm-catalogue/delete',{body:{id:'front-squat'}})).status,403);f.tables.gym_members[0].role='coach';f.tables.gym_members[0].coach_permissions=['rm'];assert.equal((await f.request('/api/rm-catalogue/delete',{body:{id:'front-squat',actor:ADMIN}})).status,200);assert.deepEqual(f.writes[0],{actor:MEMBER,item_id:'front-squat'});});

test('deductions and editable reward methods require approved admin and bind the verified actor',async()=>{const id=crypto.randomUUID(),requestId=crypto.randomUUID();for(const options of [{},{role:'coach',coach_permissions:['rm']},{role:'admin',status:'pending'}]){const f=fixture(options);for(const path of ['/api/points/deduct','/api/points/method','/api/points/method/delete'])assert.equal((await f.request(path,{body:{memberId:ADMIN,requestId,amount:3,reason:'test'}})).status,403);assert.equal(f.writes.length,0);}const f=fixture({role:'admin'});assert.equal((await f.request('/api/points/deduct',{body:{memberId:ADMIN,requestId,amount:3,reason:' 정정 ',actor:ADMIN,balance:999}})).status,200);assert.deepEqual(f.writes[0],{actor:MEMBER,p:{action:'deduct',memberId:ADMIN,requestId,amount:3,reason:'정정'}});assert.equal((await f.request('/api/points/method',{body:{id,name:'행사 참여',kind:'manual',actor:ADMIN}})).status,200);assert.deepEqual(f.writes[1],{actor:MEMBER,p:{action:'method-save',id,name:'행사 참여',kind:'manual'}});assert.equal((await f.request('/api/points/method/delete',{body:{id}})).status,200);assert.equal(f.writes[2].p.action,'method-delete');for(const patch of [{amount:-1},{amount:1.5},{reason:''},{memberId:'bad'}])assert.equal((await f.request('/api/points/deduct',{body:{memberId:ADMIN,requestId,amount:3,reason:'정정',...patch}})).status,400);});
test('rule edits forward the selected method ID without accepting client event/amount overrides',async()=>{const f=fixture({role:'admin'});assert.equal((await f.request('/api/points/rule',{body:{id:'custom',methodId:'selected-method',kind:'invented',name:'이벤트',amount:5,auto_key:'attendance'}})).status,200);assert.deepEqual(f.writes[0],{actor:MEMBER,p:{action:'rule-save',id:'custom',methodId:'selected-method',name:'이벤트',amount:5}});assert.equal((await f.request('/api/points/rule',{body:{methodId:{id:'bad'},name:'이벤트',amount:5}})).status,400);});
test('RM category management requires its own permission and keeps movement/history mutation server-side',async()=>{for(const options of [{},{role:'coach',coach_permissions:['videos']},{role:'admin',status:'suspended'}]){const f=fixture(options);assert.equal((await f.request('/api/rm-categories',{body:{action:'delete',id:'squat',targetId:'press'}})).status,403);assert.equal(f.writes.length,0);}const f=fixture({role:'coach',coach_permissions:['rm']});assert.equal((await f.request('/api/rm-categories',{body:{action:'delete',id:'squat',targetId:'press',actor:ADMIN}})).status,200);assert.deepEqual(f.writes[0],{actor:MEMBER,p:{action:'delete',id:'squat',label:undefined,targetId:'press'}});assert.equal((await f.request('/api/rm-categories',{body:{action:'arbitrary',id:'squat'}})).status,400);});

test('approved members create and pin meetups using their verified identity and whitelisted fields',async()=>{const f=fixture(),id=crypto.randomUUID(),body={id,title:'함께 운동',body:'본문',startsAt:'2026-11-04T10:30:00Z',bannerPinned:true,sendPush:true,photoIds:[],actor:ADMIN,customMessage:'injected'};let called;f.db.rpc=async(name,args)=>{called={name,args};return {data:{ok:true},error:null};};assert.equal((await f.request('/api/meetups',{body})).status,200);assert.equal(called.name,'onoff_meetup_create');assert.equal(called.args.actor,MEMBER);assert.equal(called.args.p.customMessage,undefined);assert.equal(called.args.p.sendPush,true);assert.equal((await f.request('/api/meetups/pin',{body:{id,pinned:false,actor:ADMIN}})).status,200);assert.equal(called.args.actor,MEMBER);for(const patch of [{id:'bad'},{startsAt:'bad'},{bannerPinned:'true'},{sendPush:'true'},{photoIds:['bad']}])assert.equal((await f.request('/api/meetups',{body:{...body,...patch}})).status,400);assert.equal((await fixture({status:'pending'}).request('/api/meetups',{body})).status,403);});
test('global point reset requires approved admin, explicit confirmation and a retry key',async()=>{const body={requestId:crypto.randomUUID(),confirmed:true};for(const role of ['member','coach'])assert.equal((await fixture({role}).request('/api/points/reset',{body})).status,403);const f=fixture({role:'admin'});let called;f.db.rpc=async(name,args)=>{called={name,args};return {data:{ok:true},error:null};};for(const patch of [{confirmed:false},{requestId:'bad'}])assert.equal((await f.request('/api/points/reset',{body:{...body,...patch}})).status,400);assert.equal((await f.request('/api/points/reset',{body:{...body,actor:ADMIN,deleteCoupons:true}})).status,200);assert.equal(called.name,'onoff_point_reset');assert.deepEqual(called.args,{actor:MEMBER,request_id:body.requestId});});

test('privacy acceptance uses verified identity, current version and explicit age while sharing remains optional',async()=>{const f=fixture({status:'pending'});for(const body of [{version:'old',ageOver14:true,disclosure:true},{version:'privacy-2026-11-05',gender:'female',ageOver14:false,disclosure:true}])assert.equal((await f.request('/api/privacy/accept',{body})).status,400);assert.equal((await f.request('/api/privacy/accept',{body:{version:'privacy-2026-11-05',gender:'female',ageOver14:true,disclosure:false,id:ADMIN}})).status,200);assert.equal(f.writes[0].actor,MEMBER);assert.equal(f.writes[0].p.disclosure,false);});
test('RM comparison forwards only an aggregate movement request and no caller-selected viewer',async()=>{const f=fixture();let call;f.db.rpc=async(name,args)=>{call={name,args};return {data:{total:4,lower:2,equal:1},error:null}};assert.equal((await f.request('/api/rm/comparison',{body:{movementId:'front-squat',actor:ADMIN}})).status,200);assert.deepEqual(call,{name:'onoff_rm_comparison',args:{actor:MEMBER,movement_id:'front-squat'}});assert.equal((await fixture({status:'pending'}).request('/api/rm/comparison',{body:{movementId:'front-squat'}})).status,403);});
