test('join access explains legacy-author review, preserves consent and cannot leak hidden post bodies',async()=>{const f=fixture({role:'admin'}),id=crypto.randomUUID();f.tables.gym_posts=[{id,author_id:ADMIN,category:'운동 번개',body:'private post body'}];f.tables.gym_members[1].disclosure_consent=false;f.tables.gym_members[1].privacy_version='email-signup-v1';let r=await f.request('/api/posts/access',{body:{id,actor:ADMIN}});assert.equal(r.status,200);assert.equal(r.value.code,'author_review');assert.ok(!JSON.stringify(r.value).includes('private post body'));r=await f.request('/api/posts/join',{body:{id,joined:true}});assert.equal(r.status,403);assert.equal(r.value.joinAccess.code,'author_review');assert.ok(r.value.error.includes('작성자'));assert.equal(f.writes.length,0);assert.equal(f.tables.gym_members[1].disclosure_consent,false);r=await f.request('/api/posts/join',{body:{id,joined:false}});assert.equal(r.status,200);f.tables.gym_members[1].disclosure_consent=true;r=await f.request('/api/posts/join',{body:{id,joined:true}});assert.equal(r.status,200);assert.deepEqual(f.writes.at(-1),{actor:MEMBER,target_post:id,joined:true});});

test('bootstrap preserves a private viewer own participation flag without exposing another private participant',async()=>{const f=fixture(),id=crypto.randomUUID(),privateId=crypto.randomUUID();f.tables.gym_members[0].disclosure_consent=false;f.tables.gym_members.push({id:privateId,name:'private participant',status:'approved',disclosure_consent:false});f.tables.gym_posts=[{id,author_id:ADMIN,category:'운동 번개',title:'fixture',body:'fixture',created_at:'2026-11-02T00:00:00Z'}];f.tables.gym_post_joins=[{post_id:id,user_id:MEMBER},{post_id:id,user_id:privateId}];const r=await f.request('/api/bootstrap');assert.equal(r.status,200);assert.equal(r.value.posts[0].viewerJoined,true);assert.deepEqual(r.value.posts[0].joinedIds,[]);assert.equal(r.value.posts[0].joinAccess.code,'sharing_required');assert.ok(!JSON.stringify(r.value.posts).includes('private participant'));});
test('daily ranking eligibility uses current approval, sharing consent and preference even in an operator view',async()=>{const f=fixture({role:'admin'}),PUBLIC=crypto.randomUUID(),SUSPENDED=crypto.randomUUID();f.tables.gym_members[0].disclosure_consent=false;f.tables.gym_members[1].disclosure_consent=true;f.tables.gym_members.push({id:PUBLIC,name:'공개 회원',role:'member',status:'approved',disclosure_consent:true},{id:SUSPENDED,name:'중지 회원',role:'member',status:'suspended',disclosure_consent:true});f.tables.gym_preferences=[{user_id:MEMBER,body:{rank:true}},{user_id:ADMIN,body:{rank:false}}];f.tables.gym_records=[MEMBER,ADMIN,PUBLIC,SUSPENDED].map(user_id=>({id:crypto.randomUUID(),user_id,date:'2026-11-02',body:{date:'2026-11-02',program:'WOD',section:'S1',kind:'횟수',value:'10',rank:true}}));const r=await f.request('/api/bootstrap');assert.equal(r.status,200);const rank=new Map(r.value.records.map(x=>[x.memberId,x.rank]));assert.equal(rank.get(MEMBER),false);assert.equal(rank.get(ADMIN),false);assert.equal(rank.get(PUBLIC),true);assert.equal(rank.get(SUSPENDED),false);assert.equal(f.tables.gym_preferences[0].body.rank,true);assert.equal(f.tables.gym_members[0].disclosure_consent,false);assert.ok(!f.writes.some(x=>['members','preferences'].includes(x.op)));});

test('structured record API validates using operator policy and ignores caller-authored value, score and policy',async()=>{
 const f=fixture(),sec=f.tables.gym_workouts[0].body.sections[0];Object.assign(sec,{kind:'시간',recordPolicy:{ranking:'auto',capUnit:'칼로리'}});
 const r={id:crypto.randomUUID(),date:'2026-11-02',program:'WOD',section:'S1',value:'00:01',kind:'횟수',result:{version:1,condition:'rx',status:'capped',progress:25,capUnit:'횟수',policyKey:'forged',rankingValue:9999}};
 assert.equal((await f.request('/api/records',{body:{records:[r]}})).status,200);const saved=f.writes[0].p.records[0];assert.equal(saved.kind,'시간');assert.equal(saved.value,'타임캡 · 25 cal');assert.equal(saved.result.capUnit,'칼로리');assert.equal(saved.result.rankingValue,undefined);assert.notEqual(saved.result.policyKey,'forged');
 const bad=fixture({role:'admin'});Object.assign(bad.tables.gym_workouts[0].body.sections[0],sec);assert.equal((await bad.request('/api/records',{body:{records:[r,{...r,id:crypto.randomUUID(),result:{...r.result,progress:-1}}]}})).status,400);assert.equal(bad.writes.length,0);
});
